import json; import subprocess; import sys; from datetime import datetime, timedelta, timezone; from pathlib import Path; import pytest; sys.path.insert(0, str(Path(__file__).resolve().parents[2])); from common.testing import github_workflow_timing_summary as timing_summary; format_duration = timing_summary.format_duration; format_timing_summary = timing_summary.format_timing_summary; load_run = timing_summary.load_run; main = timing_summary.main; parse_github_time = timing_summary.parse_github_time
def test_AC8_13_34_parse_github_time_handles_empty_and_utc_values() -> None: assert parse_github_time(None) is None; assert parse_github_time('') is None; parsed = parse_github_time('2026-05-20T10:02:00Z'); assert parsed is not None; assert parsed.isoformat() == '2026-05-20T10:02:00+00:00'
def test_AC8_13_34_format_duration_uses_compact_minutes() -> None: 'AC-testing.ci-structure.4'; assert format_duration(None) == 'n/a'; assert format_duration(42) == '42s'; assert format_duration(367) == '6m 7s'; _m1_run = {'url': 'https://github.example/actions/runs/1', 'createdAt': '2026-05-20T10:00:00Z', 'updatedAt': '2026-05-20T10:08:30Z', 'jobs': [{'name': 'Classify Changes', 'status': 'completed', 'conclusion': 'success', 'startedAt': '2026-05-20T10:02:00Z', 'completedAt': '2026-05-20T10:02:04Z'}, {'name': 'Backend Tests (Shard 1/5)', 'status': 'completed', 'conclusion': 'success', 'startedAt': '2026-05-20T10:02:10Z', 'completedAt': '2026-05-20T10:07:20Z'}]}; _m1_summary = format_timing_summary(_m1_run, title='CI Timing Summary'); assert '## CI Timing Summary' in _m1_summary; assert '- Queue delay: `2m 0s`' in _m1_summary; assert '- Execution window: `5m 20s`' in _m1_summary; assert '- Run wall time: `7m 20s`' in _m1_summary; assert '- Longest completed job: `Backend Tests (Shard 1/5)` at `5m 10s`' in _m1_summary; assert '| `Classify Changes` | `success` | `4s` |' in _m1_summary; _m2_run = {'url': 'https://github.example/actions/runs/2', 'createdAt': '2026-05-20T10:00:00Z', 'updatedAt': '2026-05-20T10:02:00Z', 'jobs': [{'name': 'Pending Backend', 'status': 'in_progress', 'conclusion': None, 'startedAt': '2026-05-20T10:01:00Z', 'completedAt': None}, {'name': 'Queued Backend', 'status': 'queued', 'conclusion': None, 'startedAt': None, 'completedAt': None}]}; _m2_summary = format_timing_summary(_m2_run, title='Partial Timing Summary'); assert '- Queue delay: `1m 0s`' in _m2_summary; assert '- Execution window: `1m 0s`' in _m2_summary; assert 'Longest completed job' not in _m2_summary; assert '| `Pending Backend` | `in_progress` | `n/a` | `2026-05-20T10:01:00Z` | `n/a` |' in _m2_summary; assert '| `Queued Backend` | `queued` | `n/a` | `n/a` | `n/a` |' in _m2_summary; assert timing_summary.PIPELINE_BUDGET_SECONDS == {'pr': 240, 'main': 480, 'release': 900}; _m4_verdict = timing_summary.budget_verdict(_run_taking(180, queue_seconds=20 * 60), 'pr'); assert _m4_verdict.execution_seconds == 180; assert _m4_verdict.exceeded is False; _m5_over = format_timing_summary(_run_taking(9 * 60), title='Main CI Budget', budget_kind='main'); _m5_within = format_timing_summary(_run_taking(7 * 60), title='Main CI Budget', budget_kind='main'); _m5_plain = format_timing_summary(_run_taking(9 * 60), title='Main CI Budget'); assert '- Budget `main`: execution window `9m 0s` of `8m 0s` (OVER)' in _m5_over; assert '- Budget `main`: execution window `7m 0s` of `8m 0s` (within)' in _m5_within; assert '- Budget `' not in _m5_plain
def test_AC8_13_34_load_run_invokes_gh_run_view(monkeypatch) -> None:
    calls = []
    class Result: stdout = json.dumps({'url': 'https://github.example/actions/runs/3', 'jobs': []})
    def fake_run(args, *, check, text, capture_output): calls.append((args, check, text, capture_output)); return Result()
    monkeypatch.setattr(timing_summary.subprocess, 'run', fake_run); result = load_run('owner/repo', '123'); assert result['url'] == 'https://github.example/actions/runs/3'; assert calls == [(['gh', 'run', 'view', '123', '--repo', 'owner/repo', '--json', 'createdAt,updatedAt,jobs,url,status,conclusion'], True, True, True)]
def test_AC8_13_34_main_appends_summary_file(monkeypatch, tmp_path) -> None: summary_path = tmp_path / 'summary.md'; monkeypatch.setattr(timing_summary, 'load_run', lambda repo, run_id: {'url': f'https://github.example/{repo}/{run_id}', 'createdAt': '2026-05-20T10:00:00Z', 'updatedAt': '2026-05-20T10:00:05Z', 'jobs': []}); monkeypatch.setattr(sys, 'argv', ['github_workflow_timing_summary.py', '--repo', 'owner/repo', '--run-id', '456', '--title', 'Post-merge Timing Summary', '--summary-path', str(summary_path)]); assert main() == 0; content = summary_path.read_text(encoding='utf-8'); assert '## Post-merge Timing Summary' in content; assert 'https://github.example/owner/repo/456' in content
T0 = datetime(2026, 10, 26, 8, 0, 0, tzinfo=timezone.utc); _iso = lambda moment: moment.strftime('%Y-%m-%dT%H:%M:%SZ')
def _run_taking(execution_seconds: int, *, queue_seconds: int=0) -> dict: start = T0 + timedelta(seconds=queue_seconds); end = start + timedelta(seconds=execution_seconds); middle = start + timedelta(seconds=execution_seconds // 2); job = lambda name, began, ended: {'name': name, 'status': 'completed', 'conclusion': 'success', 'startedAt': _iso(began), 'completedAt': _iso(ended)}; return {'url': 'https://github.example/actions/runs/9', 'createdAt': _iso(T0), 'updatedAt': _iso(end), 'jobs': [job('Fast', start, middle), job('Backend Tests (Shard 1/6)', start, end), job('Lint', start, start + timedelta(seconds=5)), job('Tooling', start, start + timedelta(seconds=9))]}
def _main_with(monkeypatch, tmp_path, run: dict, *flags: str, existing_comments: str='') -> tuple[int, list, Path]:
    summary_path = tmp_path / 'summary.md'; gh_calls: list[list[str]] = []
    def fake_run(args, *, check, text, capture_output):
        if args[:3] == ['gh', 'issue', 'view']: on_budget_issue = args[3] == timing_summary.PIPELINE_BUDGET_ISSUE; assert on_budget_issue and args[4:6] == ['--repo', 'owner/repo']; return subprocess.CompletedProcess(args, 0, stdout=existing_comments, stderr='')
        gh_calls.append(args); return subprocess.CompletedProcess(args, 0, stdout='', stderr='')
    monkeypatch.setattr(timing_summary, 'load_run', lambda repo, run_id: run); monkeypatch.setattr(timing_summary.subprocess, 'run', fake_run); code = main(['--repo', 'owner/repo', '--run-id', '9', '--title', 'Main CI Budget', '--summary-path', str(summary_path), *flags]); return (code, gh_calls, summary_path)
@pytest.mark.parametrize(('kind', 'budget_seconds'), [('pr', 240), ('main', 480), ('release', 900)])
def test_budget_verdict_is_over_only_above_the_budget(kind: str, budget_seconds: int) -> None: at_budget = timing_summary.budget_verdict(_run_taking(budget_seconds), kind); one_second_over = timing_summary.budget_verdict(_run_taking(budget_seconds + 1), kind); assert at_budget.exceeded is False; assert one_second_over.exceeded is True; assert one_second_over.budget_seconds == budget_seconds
def test_enforce_fails_an_over_budget_run_and_comments_on_the_issue(monkeypatch, tmp_path) -> None: code, gh_calls, summary_path = _main_with(monkeypatch, tmp_path, _run_taking(9 * 60), '--budget', 'main', '--enforce', '--comment'); assert code == 1; assert len(gh_calls) == 1; assert gh_calls[0][:6] == ['gh', 'issue', 'comment', '2688', '--repo', 'owner/repo']; body = gh_calls[0][-1]; assert '9m 0s' in body and '8m 0s' in body and ('`main`' in body); assert 'https://github.example/actions/runs/9' in body; assert body.index('Backend Tests (Shard 1/6)') < body.index('Fast'); assert body.index('Fast') < body.index('Tooling'); assert 'Lint' not in body; assert '(OVER)' in summary_path.read_text(encoding='utf-8')
def test_enforce_passes_a_run_within_budget_without_commenting(monkeypatch, tmp_path) -> None: code, gh_calls, _ = _main_with(monkeypatch, tmp_path, _run_taking(7 * 60), '--budget', 'main', '--enforce', '--comment'); assert code == 0; assert gh_calls == []
def test_a_pr_run_over_budget_only_prints(monkeypatch, tmp_path, capsys) -> None: code, gh_calls, summary_path = _main_with(monkeypatch, tmp_path, _run_taking(6 * 60), '--budget', 'pr'); assert code == 0; assert gh_calls == []; assert '::warning::Pipeline budget exceeded' in capsys.readouterr().out; assert '(OVER)' in summary_path.read_text(encoding='utf-8')
def test_enforce_fails_when_no_job_has_run(monkeypatch, tmp_path) -> None: empty = {'url': 'u', 'createdAt': _iso(T0), 'updatedAt': _iso(T0), 'jobs': []}; enforced, _, _ = _main_with(monkeypatch, tmp_path, empty, '--budget', 'release', '--enforce'); printed, _, _ = _main_with(monkeypatch, tmp_path, empty, '--budget', 'release'); assert enforced == 1; assert printed == 0
def test_enforce_still_fails_when_the_issue_comment_fails(monkeypatch, tmp_path, capsys) -> None:
    def failing_run(args, *, check, text, capture_output): raise subprocess.CalledProcessError(1, args)
    monkeypatch.setattr(timing_summary, 'load_run', lambda repo, run_id: _run_taking(16 * 60)); monkeypatch.setattr(timing_summary.subprocess, 'run', failing_run); code = main(['--repo', 'owner/repo', '--run-id', '9', '--summary-path', str(tmp_path / 'summary.md'), '--budget', 'release', '--enforce', '--comment']); assert code == 1; assert '::warning::Could not comment on issue 2688' in capsys.readouterr().out
def test_enforce_and_comment_need_a_budget(tmp_path) -> None:
    for flags in (['--enforce'], ['--comment']):
        with pytest.raises(SystemExit) as raised: main(['--repo', 'owner/repo', '--run-id', '9', '--summary-path', str(tmp_path / 'summary.md'), *flags])
        assert raised.value.code == 2
def test_a_rerun_does_not_comment_twice_for_the_same_run(monkeypatch, tmp_path) -> None: run = _run_taking(9 * 60); flags = ('--budget', 'main', '--enforce', '--comment'); first, first_calls, _ = _main_with(monkeypatch, tmp_path, run, *flags); again, again_calls, _ = _main_with(monkeypatch, tmp_path, run, *flags, existing_comments='Pipeline budget exceeded ... Run: ' + run['url']); other_run, other_calls, _ = _main_with(monkeypatch, tmp_path, run, *flags, existing_comments='Run: https://github.example/actions/runs/1'); assert (first, len(first_calls)) == (1, 1); assert (again, again_calls) == (1, []); assert (other_run, len(other_calls)) == (1, 1)
def test_the_comment_goes_to_the_one_budget_issue(monkeypatch, tmp_path) -> None: _, gh_calls, _ = _main_with(monkeypatch, tmp_path, _run_taking(9 * 60), '--budget', 'main', '--comment'); assert timing_summary.PIPELINE_BUDGET_ISSUE == '2688'; assert gh_calls[0][3] == timing_summary.PIPELINE_BUDGET_ISSUE
def test_a_comment_for_a_longer_run_id_does_not_count_as_this_run(monkeypatch, tmp_path) -> None: run = _run_taking(9 * 60); run['url'] = 'https://github.example/actions/runs/9'; code, gh_calls, _ = _main_with(monkeypatch, tmp_path, run, '--budget', 'main', '--comment', existing_comments='Run: https://github.example/actions/runs/90'); assert (code, len(gh_calls)) == (0, 1)
